 *   `.positive()` thành một lỗi 400 khó hiểu ở tận server.
 */
export function kep(gt: number, min: number, max: number, macDinh: number): number {
  if (!Number.isFinite(gt)) return macDinh;
  return Math.min(max, Math.max(min, gt));
}

